// Strip markup so the LLM sees only readable text, then fingerprint it for change detection.
const MAX_CHARS = 80000;
const ENTITIES = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', rsquo: "'", lsquo: "'", rdquo: '"', ldquo: '"', ndash: '-', mdash: '-', hellip: '...' };

const decode = (s) =>
  s.replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(Number(n)))
    .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
    .replace(/&([a-z]+);/gi, (m, n) => ENTITIES[n.toLowerCase()] ?? m);

const text = decode(
  $json.data
    .replace(/<(script|style|noscript|svg|nav|footer|header|iframe)\b[\s\S]*?<\/\1>/gi, ' ')
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<\/(p|div|li|tr|h[1-6]|section|table|ul|ol)>|<br\s*\/?>/gi, '\n')
    .replace(/<\/t[dh]>/gi, ' | ')
    .replace(/<[^>]+>/g, ' ')
);

const lines = [];
for (const raw of text.split('\n')) {
  const line = raw.replace(/\s+/g, ' ').trim();
  // Very long lines are embedded JSON blobs, not prose
  if (!line || line.length > 1500 || line === lines[lines.length - 1]) continue;
  lines.push(line);
}
const cleaned = lines.join('\n').slice(0, MAX_CHARS);

const source = $('Load enabled sources').item.json;
const hash = require('crypto').createHash('sha256').update(cleaned).digest('hex');
const status = cleaned.length < 2000 ? 'bad_page' : hash === source.previous_hash ? 'unchanged' : 'changed';
return { json: { ...source, cleaned_text: cleaned, content_hash: hash, status } };

// One call per changed page. Every field is required (nullable): without that the model
// silently omits fields it is unsure about.
const PROMPT = "You extract personal loan products from the text of a lender's web page.

Rules:
- Return only personal loan products the lender offers on this page. Do not invent products.
- Use only facts stated in the page text. Never use outside knowledge.
- If eligibility is the same for everyone, return one product named "<Lender> Personal Loan". If it differs by employment type (for example salaried vs self-employed), return one product per segment, named "<Lender> Personal Loan (Salaried)" and so on, each with only that segment's own criteria and its allowed_employment limited to that segment. Return separate products otherwise only when the page clearly lists distinct loans.
- Use null for anything the page does not state. Never guess.
- Interest rates are annual percentages (p.a.). Convert monthly rates to annual. rate_min is the lowest rate quoted ("starting from"), rate_max the highest, null if none is quoted.
- min_income is the minimum NET MONTHLY income in INR as a plain number (convert lakh/thousand). Ignore annual-income figures unless converted.
- min_credit_score is the minimum CIBIL/credit score if stated, even when described as preferred.
- min_age and max_age are in years. A range such as "21 to 60 years" gives min_age 21 and max_age 60; "up to 58 years" gives max_age 58.
- allowed_employment lists who may apply, using only: Salaried, Self-Employed, Business. null if not stated.
- residual_criteria: one short sentence for any other eligibility conditions not captured above (for example work experience, residence, loan purpose). null if none.";
const SCHEMA = {"type": "OBJECT", "properties": {"products": {"type": "ARRAY", "items": {"type": "OBJECT", "properties": {"product_name": {"type": "STRING"}, "rate_min": {"type": "NUMBER", "nullable": true}, "rate_max": {"type": "NUMBER", "nullable": true}, "min_income": {"type": "NUMBER", "nullable": true}, "min_credit_score": {"type": "INTEGER", "nullable": true}, "min_age": {"type": "INTEGER", "nullable": true}, "max_age": {"type": "INTEGER", "nullable": true}, "allowed_employment": {"type": "ARRAY", "nullable": true, "items": {"type": "STRING", "enum": ["Salaried", "Self-Employed", "Business"]}}, "residual_criteria": {"type": "STRING", "nullable": true}}, "propertyOrdering": ["product_name", "rate_min", "rate_max", "min_income", "min_credit_score", "min_age", "max_age", "allowed_employment", "residual_criteria"], "required": ["product_name", "rate_min", "rate_max", "min_income", "min_credit_score", "min_age", "max_age", "allowed_employment", "residual_criteria"]}}}, "required": ["products"]};
return { json: { ...$json, request: {
  systemInstruction: { parts: [{ text: PROMPT }] },
  contents: [{ parts: [{ text: `Lender: ${$json.lender}

Page text:
${$json.cleaned_text}` }] }],
  generationConfig: { temperature: 0, responseMimeType: 'application/json', responseSchema: SCHEMA },
} } };

// Never trust LLM output: enforce the contract before anything reaches the database.
const ctx = $('Build Gemini request').item.json;
const EMPLOYMENT = new Set(['Salaried', 'Self-Employed', 'Business']);
const inRange = (v, lo, hi) => (typeof v === 'number' && Number.isFinite(v) && v >= lo && v <= hi ? v : null);

let parsed = { products: [] };
try {
  parsed = JSON.parse($json.candidates[0].content.parts[0].text);
} catch (error) {
  // fall through with no products; the workflow records an extract failure
}

const seen = new Set();
const products = [];
for (const p of parsed.products ?? []) {
  const name = String(p.product_name ?? '').trim().slice(0, 120);
  if (!name || seen.has(name.toLowerCase())) continue;
  seen.add(name.toLowerCase());

  let rateMin = inRange(p.rate_min, 0.5, 60);
  let rateMax = inRange(p.rate_max, 0.5, 60);
  if (rateMin !== null && rateMax !== null && rateMin > rateMax) [rateMin, rateMax] = [rateMax, rateMin];

  let minAge = inRange(p.min_age, 18, 100);
  let maxAge = inRange(p.max_age, 18, 100);
  if (minAge !== null && maxAge !== null && minAge > maxAge) minAge = maxAge = null;

  const employment = Array.isArray(p.allowed_employment)
    ? [...new Set(p.allowed_employment.filter((e) => EMPLOYMENT.has(e)))]
    : [];
  const score = inRange(p.min_credit_score, 300, 900);

  products.push({
    product_name: name,
    rate_min: rateMin,
    rate_max: rateMax,
    min_income: inRange(p.min_income, 1000, 10000000),
    min_credit_score: score === null ? null : Math.round(score),
    min_age: minAge === null ? null : Math.round(minAge),
    max_age: maxAge === null ? null : Math.round(maxAge),
    allowed_employment: employment.length ? employment : null,
    residual_criteria: p.residual_criteria ? String(p.residual_criteria).slice(0, 300) : null,
  });
}
return { json: { source_id: ctx.source_id, lender: ctx.lender, content_hash: ctx.content_hash, cleaned_text: ctx.cleaned_text, products } };
